'use strict';
const ADNIPO=(()=>{
const legacySeed={version:1,cult:{title:'Culto da Fé',date:'2026-10-14',time:'20:00',place:'ADNIPO · Local a confirmar'},songs:[
{id:'caminho',name:'Caminho de Fé',key:'C',bpm:76,notes:'Entrada suave. Repetir o refrão duas vezes e finalizar em C.',lyrics:'Caminho de fé, eu sigo contigo\nTua presença é meu abrigo\nEm cada passo, em cada manhã\nMeu coração em Ti descansará\n\nTua luz acende a esperança\nTua paz renova a confiança\nJuntos cantamos, Senhor, para Ti\nPela fé eu vou prosseguir',chords:'Intro | C | G | Am | F |\nEstrofe | C | G | Am | F |\nRefrão | F | C | G | Am |\nFinal | F | G | C | C |',scoreLink:'',gradeLink:'',projectionLink:'',voicesLink:'',videoLink:''},
{id:'luz',name:'Tua Luz Nos Guia',key:'G',bpm:92,notes:'Começar com teclado. Bateria entra no primeiro refrão.',lyrics:'Quando o dia parece escuro\nTua luz nos mostra o futuro\nTuas mãos sustentam o andar\nE nos ensinam a confiar\n\nTua luz nos guia, Senhor\nNos reúne em Teu amor\nUma voz, um só coração\nSeguiremos Tua direção',chords:'Intro | G | D | Em | C |\nEstrofe | G | D | Em | C |\nRefrão | C | G | D | Em |\nFinal | C | D | G | G |',scoreLink:'',gradeLink:'',projectionLink:'',voicesLink:'',videoLink:''},
{id:'unidos',name:'Unidos em Louvor',key:'D',bpm:108,notes:'Celebrativo. Todos entram juntos; reduzir a dinâmica na segunda estrofe.',lyrics:'Somos muitos, uma só canção\nCada voz entrega o coração\nEm Teu nome vamos caminhar\nTua bondade vamos celebrar\n\nUnidos em louvor, unidos pela fé\nTua igreja canta e permanece em pé\nQue o nosso canto anuncie o amor\nToda a nossa vida entregamos ao Senhor',chords:'Intro | D | A | Bm | G |\nEstrofe | D | A | Bm | G |\nRefrão | G | D | A | Bm |\nFinal | G | A | D | D |',scoreLink:'',gradeLink:'',projectionLink:'',voicesLink:'',videoLink:''}],
events:[{id:'ensaio',title:'Ensaio do ministério',date:'2026-10-13',time:'19:30',place:'Sala de música · Exemplo',notes:'Revisar entradas, vozes e transições dos três louvores.'},{id:'culto',title:'Culto da Fé',date:'2026-10-14',time:'20:00',place:'Templo · Exemplo',notes:'Chegada da equipe 30 minutos antes para passagem de som.'}],
notices:[{id:'aviso',title:'Vamos preparar o próximo culto',text:'Ouça sua linha do kit de vozes antes do ensaio. Confira o tom e as entradas na grade de cada louvor.',author:'Coordenação · Exemplo'}],
words:[{id:'palavra',title:'Uma fé que caminha',reference:'Hebreus 11:1',author:'Equipe pastoral · Exemplo',date:'2026-10-14',text:'Reflexão fictícia para o piloto.\n\nA fé orienta nossos passos mesmo quando o caminho ainda não está claro. Como ministério, nos preparamos juntos e servimos com humildade.\n\nPara conversar: de que forma podemos apoiar uns aos outros durante esta semana?',link:''}]};

const clone=value=>structuredClone(value);
const keys=['C','C#','Db','D','D#','Eb','E','F','F#','Gb','G','G#','Ab','A','A#','Bb','B','Cm','C#m','Dm','D#m','Ebm','Em','Fm','F#m','Gm','G#m','Am','A#m','Bbm','Bm'];
const defaultInstruments=['Geral','Voz','Soprano','Contralto','Tenor','Baixo vocal','Teclado','Piano','Violão','Guitarra','Baixo','Bateria','Percussão','Violino','Flauta','Saxofone'].map((name,index)=>({id:index===0?'geral':'instrument-'+index,name,kind:index===0?'general':index<6?'voice':'instrument'}));
function validURL(value){if(!value)return '';try{const url=new URL(value);if(!['http:','https:'].includes(url.protocol)||url.username||url.password)throw Error();return url.href;}catch{throw Error('Use um endereço completo começando por https:// ou http://.');}}
function emptyDepartment(id,name,date=new Date().toISOString().slice(0,10)){return {id,name,cult:{title:'Próximo culto',date,time:'19:30',place:'Local a confirmar'},repertoire:[],events:[],notices:[]};}
function migrate(input){
const data=clone(input);if(data.version===4){for(const song of data.songs||[])song.resources??=[];if(!data.instruments){data.instruments=clone(defaultInstruments);for(const song of data.songs||[])for(const resource of song.resources||[]){if(!data.instruments.some(item=>item.name===resource.instrument))data.instruments.push({id:'imported-'+data.instruments.length,name:resource.instrument,kind:'instrument'});}}return data;}
if(data.version!==1||!Array.isArray(data.songs)||!data.cult||!Array.isArray(data.events)||!Array.isArray(data.notices)||!Array.isArray(data.words))throw Error('Arquivo de dados incompatível.');
return {version:4,songs:data.songs.map(song=>({...song,artist:'',originalKey:song.key,category:'',audioLink:'',pdfLink:'',departmentIds:['fe']})),departments:[{id:'fe',name:'Culto da F\u00e9',cult:data.cult,repertoire:data.songs.map(song=>({songId:song.id,key:song.key,notes:''})),events:data.events,notices:data.notices},emptyDepartment('japones','Culto de Japon\u00eas',data.cult.date),emptyDepartment('inoti','Inoti',data.cult.date)],words:data.words};
}
function text(value,label,max=20000){if(typeof value!=='string'||value.length>max)throw Error('Campo inválido: '+label+'.');}
function dateTime(item){text(item.date,'data');const match=/^(\d{4})-(\d{2})-(\d{2})$/.exec(item.date);if(!match||new Date(item.date+'T12:00:00Z').toISOString().slice(0,10)!==item.date)throw Error('Data inválida.');if(item.time!==undefined&&!/^(?:[01]\d|2[0-3]):[0-5]\d$/.test(item.time))throw Error('Horário inválido.');}
function collection(items,limit,label){if(!Array.isArray(items)||items.length>limit)throw Error('Lista inválida: '+label+'.');const ids=new Set();for(const item of items){if(!item||typeof item.id!=='string'||!item.id||item.id.length>100||ids.has(item.id))throw Error('Identificadores inválidos em '+label+'.');ids.add(item.id);}return ids;}
function fields(item,names){for(const name of names){text(item[name],name);if(/Link$|^link$/.test(name))validURL(item[name]);}}
function validate(input){
 const data=migrate(input);data.instruments??=clone(defaultInstruments);collection(data.instruments,200,'instrumentos e vozes');const instrumentNames=new Set();for(const item of data.instruments){fields(item,['name','kind']);const normalized=item.name.trim().normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLocaleLowerCase('pt-BR');if(!normalized||instrumentNames.has(normalized)||!['general','voice','instrument'].includes(item.kind))throw Error('Nome ou tipo inválido no cadastro de instrumentos e vozes.');instrumentNames.add(normalized);}if(!data.instruments.some(item=>item.id==='geral'&&item.name==='Geral'&&item.kind==='general'))throw Error('A classificação Geral deve ser preservada.');const songIds=collection(data.songs,1000,'louvores');collection(data.words,1000,'palavras');const departmentIds=collection(data.departments,100,'departamentos');if(!departmentIds.size)throw Error('Cadastre ao menos um departamento.');for(const department of data.departments){fields(department,['name']);if(!department.name.trim())throw Error('Informe o nome do departamento.');}
 for(const song of data.songs){song.resources??=[];fields(song,['name','artist','key','originalKey','category','notes','lyrics','chords','scoreLink','gradeLink','projectionLink','voicesLink','videoLink','audioLink','pdfLink']);if(!song.name.trim()||!keys.includes(song.key)||!keys.includes(song.originalKey))throw Error('Informe título e tonalidades válidas.');if(!Array.isArray(song.departmentIds)||song.departmentIds.some(id=>!departmentIds.has(id))||new Set(song.departmentIds).size!==song.departmentIds.length)throw Error('Departamentos inválidos no louvor.');if(!Number.isFinite(song.bpm)||song.bpm<30||song.bpm>250)throw Error('Andamento inválido.');collection(song.resources,200,'materiais');for(const resource of song.resources){fields(resource,['type','instrument','label','url']);if(!['partitura','cifra','letra','projecao','vozes','videoaula'].includes(resource.type)||!resource.instrument.trim()||!resource.label.trim()||(!resource.url&&!(resource.storage==='local'&&typeof resource.fileId==='string'&&/^[a-z0-9-]+$/i.test(resource.fileId))))throw Error('Informe tipo, instrumento, nome e endereço do material.');if(!data.instruments.some(item=>item.name===resource.instrument))throw Error('Cadastre o instrumento ou voz antes de associar o material.');validURL(resource.url);}}
 for(const program of data.departments){if(!program.cult)throw Error('Culto inválido.');fields(program.cult,['title','date','time','place']);if(!program.cult.title.trim())throw Error('Informe o nome do culto.');dateTime(program.cult);collection(program.events,1000,'agenda');collection(program.notices,1000,'comunicados');if(!Array.isArray(program.repertoire)||program.repertoire.length>1000)throw Error('Repertório inválido.');const used=new Set();for(const entry of program.repertoire){if(!entry||!songIds.has(entry.songId)||used.has(entry.songId)||!keys.includes(entry.key)||!data.songs.find(s=>s.id===entry.songId).departmentIds.includes(program.id))throw Error('Louvor ou tom inválido no repertório deste departamento.');text(entry.notes,'observações');used.add(entry.songId);}for(const event of program.events){fields(event,['title','date','time','place','notes']);dateTime(event);}for(const notice of program.notices)fields(notice,['title','text','author']);}
 for(const word of data.words){fields(word,['title','reference','author','date','text','link']);dateTime(word);}
 return data;
}
function authorizeUpdate(user,before,after){
if(user.role==='admin')return true;
if(user.role!=='department_admin'||!user.departmentId)return false;
const previous=before.departments.find(d=>d.id===user.departmentId),next=after.departments.find(d=>d.id===user.departmentId);if(!previous||!next||previous.name!==next.name)return false;
const withoutOwn=data=>({...data,departments:data.departments.map(department=>department.id===user.departmentId?{id:department.id,name:department.name}:department)});
return JSON.stringify(withoutOwn(before))===JSON.stringify(withoutOwn(after));
}
const normalize=value=>String(value??'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLocaleLowerCase('pt-BR');
function searchSongs(songs,{query='',category='',key='',favoritesOnly=false,favorites=[]}={}){const terms=normalize(query).trim().split(/\s+/).filter(Boolean);return songs.filter(song=>terms.every(term=>normalize([song.name,song.artist,song.key,song.originalKey,song.category].join(' ')).includes(term))&&(!category||song.category===category)&&(!key||song.key===key||song.originalKey===key)&&(!favoritesOnly||favorites.includes(song.id)));}
const seed=validate(legacySeed);
return {seed,validate,migrate,validURL,authorizeUpdate,searchSongs,keys,emptyDepartment};
})();
